BEGIN;


-- REVIEWED MATERIAL COST DENOMINATIONS
-- Values are copper pieces. Evidence comes from the original catalog.
-- Complex per-target, composite, and conditional prices are excluded.
DO $material_units$
DECLARE item jsonb; actual_cost bigint; actual_text text; total integer;
BEGIN
  LOCK TABLE spell_data IN SHARE ROW EXCLUSIVE MODE;
