"}, {"referenceKey": "draconic_transformation", "old": 500, "cost": 50000, "evidence": "статуэтка дракона стоимостью не менее 500 зм"}, {"referenceKey": "drawmijs_instant_summons", "old": 1000, "cost": 100000, "evidence": "сапфир стоимостью 1000 зм"}, {"referenceKey": "find_familiar", "old": 10, "cost": 1000, "evidence": "стоящие 10 зм уголь, благовония и травы, сжигаемые в огне в латунной жаровне"}, {"referenceKey": "find_the_path", "old": 100, "cost": 10000, "evidence": "набор инструментов для ворожбы — такой, как кости, палочки из слоновой кости, карты, зубы или резные руны — стоящий 100 зм, а также предмет из места, которое вы хотите найти"}, {"referenceKey": "fizbans_platinum_shield", "old": 500, "cost": 50000, "evidence": "покрытая платиной чешуя Дракона, стоимостью не менее 500 зм"}, {"referenceKey": "forcecage", "old": 1500, "cost": 150000, "evidence": "порошок рубина, стоящий 1 500 зм"}, {"referenceKey": "fortunes_favor", "old": 100, "cost": 10000, "evidence": "жемчужина, стоящая как минимум 100 зм, расходуемая заклинанием"}, {"referenceKey": "galders_speedy_courier", "old": 25, "cost": 2500, "evidence": "25 зм или минералы равноценной стоимости, расходуемые заклинанием"}, {"referenceKey": "gate", "old": 5000, "cost": 500000, "evidence": "бриллиант, стоящий как минимум 5 000 зм"}, {"referenceKey": "glyph_of_warding", "old": 200, "cost": 20000, "evidence": "благовония и растолчённый бриллиант, стоящий как минимум 200 зм, расходуемый заклинанием"}, {"referenceKey": "greater_restoration", "old": 100, "cost": 10000, "evidence": "бриллиантовая пыль, стоящая как минимум 100 зм, расходуемая заклинанием"}, {"referenceKey": "green_flame_blade", "old": 1, "cost": 10, "evidence": "рукопашное оружие стоимостью не менее 1 см"}, {"referenceKey": "hallow", "old": 1000, "cost": 100000, "evidence": "травы, масла и благовония, стоящие как минимум 1 000 зм, расходуемые заклинанием"}, {"referenceKey": "heroes_feast", "old": 1000, "cost": 100000, "evidence": "инкрустированная д