00, "cost": 100000, "evidence": "драгоценный камень, стоящий как минимум 1 000 зм, расходуемый заклинанием"}, {"referenceKey": "plane_shift", "old": 250, "cost": 25000, "evidence": "раздвоенный металлический прут, стоящий как минимум 250 зм, настроенный на конкретный план существования"}, {"referenceKey": "programmed_illusion", "old": 25, "cost": 2500, "evidence": "кусок овечьей шерсти и порошок нефрита, стоящий как минимум 25 зм"}, {"referenceKey": "project_image", "old": 5, "cost": 500, "evidence": "ваша небольшая копия, изготовленная из материала, стоящего не менее 5 зм"}, {"referenceKey": "raise_dead", "old": 500, "cost": 50000, "evidence": "бриллиант, стоящий как минимум 500 зм, расходуемый заклинанием"}, {"referenceKey": "reincarnate", "old": 1000, "cost": 100000, "evidence": "редкие масла и мази, стоящие как минимум 1 000 зм, расходуемые заклинанием"}, {"referenceKey": "resurrection", "old": 1000, "cost": 100000, "evidence": "бриллиант, стоящий как минимум 1 000 зм, расходуемый заклинанием"}, {"referenceKey": "revivify", "old": 300, "cost": 30000, "evidence": "бриллианты, стоящие в сумме 300 зм, расходуемые заклинанием"}, {"referenceKey": "scrying", "old": 1000, "cost": 100000, "evidence": "фокусировка, стоящая как минимум 1000 зм, такая, как хрустальный шар, серебряное зеркало или чаша со святой водой"}, {"referenceKey": "sequester", "old": 5000, "cost": 500000, "evidence": "смесь порошков из бриллианта, изумруда, рубина и сапфира, стоящая как минимум 5 000 зм, расходуемая заклинанием"}, {"referenceKey": "shadow_of_moil", "old": 150, "cost": 15000, "evidence": "глазное яблоко Нежити, заключенное в драгоценный камень стоимостью не менее 150 зм"}, {"referenceKey": "shapechange", "old": 1500, "cost": 150000, "evidence": "нефритовый обруч, стоящий как минимум 1 500 зм, который вы должны надеть на голову перед накладыванием заклинания"}, {"referenceKey": "simulacrum", "old": 1500, "cost": 150000, "evidence": "снег или лёд в количестве, достаточном для создания то